begin;
create temporary table dic_import_test_results(result jsonb);
do $$
declare a uuid:=gen_random_uuid(); b uuid:=gen_random_uuid(); pending uuid:=gen_random_uuid();
 doc jsonb; p jsonb; r jsonb; bad jsonb; archived jsonb; checks text[]:=array[]::text[]; rejected boolean;
begin
 doc:=$json${"format":"the-dial-in-collective-prototype-backup","exportedAt":"2026-10-06T00:00:00Z","data":{"schemaVersion":1,"mode":"personal","theme":"dark","preferences":"Test preferences","activeSetupId":"s","setups":[{"id":"s","name":"Imported test","activeVersionId":"v","versions":[{"id":"v","createdAt":"2026-10-06T00:00:00Z","machine":"","grinder":"","burrs":"","calibrationId":"g","calibrations":[{"id":"g","min":0,"max":5}],"baskets":[{"id":"b","name":"18 g basket","doseG":18,"archived":false}],"defaultBasketId":"b","tempUnit":"F","advanced":{"temperature":true,"slowFeed":false,"baskets":false},"slowFeed":false}],"workspaces":{"v":{"currentCoffeeId":"c1","coffees":{"c1":{"style":"Turbo","currentFamilies":{"Turbo":"f"}},"c2":{"style":"Traditional","currentFamilies":{}}}}}}],"coffees":[{"id":"c1","name":"Sample One","roaster":"Test roaster","createdAt":"2026-09-01T00:00:00Z","bags":[{"id":"bag1","roastDate":"","frozen":false,"archived":false}]},{"id":"c2","name":"Sample Natural","roaster":"Test roaster two","createdAt":"2026-09-01T00:00:00Z","roastLevel":"Light","roastLevelSource":"estimated","bags":[{"id":"bag2","roastDate":"","frozen":false,"archived":false}]}],"families":[{"id":"f","coffeeId":"c1","style":"Turbo","createdAt":"2026-09-01T00:00:00Z"}],"shots":[{"id":"one","legacyId":"old-one","coffeeId":"c1","setupId":"s","setupVersionId":"v","basketId":"b","calibrationId":"g","bagId":"bag1","familyId":null,"timestamp":"2026-09-01T01:00:00.123Z","style":"Turbo","doseG":18,"yieldG":40,"timeS":16,"grindSetting":null,"tempC":89.4,"feedMode":null,"tasteScales":{"extraction":2,"body":3,"clarity":4,"sweetness":4,"astringency":1},"notes":"Private original note","snapshot":{"basketDoseG":18,"grinderMin":0,"grinderMax":5}},{"id":"two","legacyId":"old-two","coffeeId":"c1","setupId":"s","setupVersionId":"v","basketId":"b","calibrationId":"g","bagId":"bag1","familyId":"f","timestamp":"2026-09-02T01:00:00.456Z","style":"Turbo","doseG":18,"yieldG":36,"timeS":100,"grindSetting":0,"tempC":89.4,"feedMode":null,"tasteScales":{"extraction":3,"body":3,"clarity":5,"sweetness":5,"astringency":1},"notes":"","snapshot":{"basketDoseG":18,"grinderMin":0,"grinderMax":5}},{"id":"three","legacyId":"old-three","coffeeId":"c1","setupId":"s","setupVersionId":"v","basketId":"b","calibrationId":"g","bagId":"bag1","familyId":"f","timestamp":"2026-09-03T01:00:00.789Z","style":"Turbo","doseG":20,"yieldG":40,"timeS":27,"grindSetting":0.2,"tempC":null,"feedMode":null,"tasteScales":{"extraction":3,"body":3,"clarity":5,"sweetness":5,"astringency":1},"notes":"","snapshot":{"basketDoseG":18,"grinderMin":0,"grinderMax":5}}],"experiments":[],"legacyArchive":{"shared":{"aggregate":{"count":99}}},"legacyEnrichment":{"keep":"Original recommendation history"}}}$json$::jsonb;
 insert into auth.users(id,email,email_confirmed_at) values(a,'import-a-'||a||'@example.invalid',now()),(b,'import-b-'||b||'@example.invalid',now()),(pending,'import-pending-'||pending||'@example.invalid',now());
 update private.beta_members set enabled=true,admitted_at=now() where owner_id in(a,b);
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 p:=public.dic_preview_import(a,doc);
 if (p->>'shots')::int<>3 or (p->>'coffees')::int<>2 or (p->>'dialedInShots')::int<>2 then raise exception 'Wrong preview counts'; end if;
 checks:=array_append(checks,'Preview validates all records and computes taste success');
 if (p->>'missingGrind')::int<>1 or (p->>'unknownFeed')::int<>3 then raise exception 'Unknowns lost'; end if;
 checks:=array_append(checks,'Missing grind and unknown feed preserved');
 if (p->>'canImport')::boolean then raise exception 'Write gate open'; end if;
 checks:=array_append(checks,'Backup readiness gate closed');
 r:=public.dic_commit_import(a,doc,p->>'reviewHash',true);
 if r->>'code'<>'recovery_required' then raise exception 'Gate bypass'; end if;
 checks:=array_append(checks,'Commit cannot bypass recovery gate');
 rejected:=false;begin perform public.dic_preview_import(b,doc);exception when insufficient_privilege then rejected:=true;end;
 if not rejected then raise exception 'Wrong owner accepted';end if;
 checks:=array_append(checks,'Cross-account request rejected');
 rejected:=false;begin perform public.dic_preview_import(null,doc);exception when insufficient_privilege then rejected:=true;end;
 if not rejected then raise exception 'Null owner accepted';end if;
 checks:=array_append(checks,'Missing account binding rejected');
 rejected:=false;begin perform count(*) from private.import_batches;exception when insufficient_privilege then rejected:=true;end;
 if not rejected then raise exception 'Archive readable';end if;
 checks:=array_append(checks,'Raw import archives not directly client-readable');
 rejected:=false;begin update private.import_control set saves_enabled=true,recovery_verified_at=now();exception when insufficient_privilege then rejected:=true;end;
 if not rejected then raise exception 'Gate client editable';end if;
 checks:=array_append(checks,'Browser cannot enable import gate');
 execute 'reset role';
 if exists(select 1 from public.setups where owner_id=a) or exists(select 1 from public.shots where owner_id=a) or exists(select 1 from private.import_batches where owner_id=a) then raise exception 'Preview left data';end if;
 checks:=array_append(checks,'Preview leaves no persisted account records');
 -- Only this temporary test transaction enables the gate.
 update private.import_control set saves_enabled=true,recovery_verified_at=now();
 execute 'set local role authenticated';
 rejected:=false;begin perform public.dic_commit_import(a,doc,'wrong',true);exception when invalid_parameter_value then rejected:=true;end;
 if not rejected then raise exception 'Unreviewed file accepted';end if;
 checks:=array_append(checks,'Exact reviewed-file hash required');
 rejected:=false;begin perform public.dic_commit_import(a,doc,p->>'reviewHash',false);exception when invalid_parameter_value then rejected:=true;end;
 if not rejected then raise exception 'Missing recovery acknowledgement accepted';end if;
 checks:=array_append(checks,'Recovery acknowledgement required');
 r:=public.dic_commit_import(a,doc,p->>'reviewHash',true);
 if not (r->>'imported')::boolean then raise exception 'Import failed';end if;
 checks:=array_append(checks,'Atomic confirmed import succeeds in controlled test');
 r:=public.dic_commit_import(a,doc,p->>'reviewHash',true);
 if not (r->>'alreadyImported')::boolean then raise exception 'Duplicate not recognized';end if;
 checks:=array_append(checks,'Retry returns existing import rather than duplicating');
 execute 'reset role';
 if (select count(*) from public.shots where owner_id=a)<>3 then raise exception 'Repeated shots';end if;
 checks:=array_append(checks,'Duplicate retry keeps exact shot count');
 if not exists(select 1 from public.shots where owner_id=a and legacy_id='old-one' and grind_setting is null and feed_mode='unknown') then raise exception 'Missing observation altered';end if;
 checks:=array_append(checks,'Null grind is not converted to zero');
 if not exists(select 1 from public.shots where owner_id=a and legacy_id='old-two' and grind_setting=0 and time_s=100 and is_dialed_in and style='Turbo') then raise exception 'Style reclassification or zero loss';end if;
 checks:=array_append(checks,'Zero grind and successful 100-second Turbo preserved');
 if not exists(select 1 from public.shots where owner_id=a and dose_g=20 and equipment_snapshot->>'basket_dose_g'='18') then raise exception 'Dose boundary wrongly applied';end if;
 checks:=array_append(checks,'Basket Dose recommendation does not block historical observation');
 if not exists(select 1 from public.shots where owner_id=a and pulled_at='2026-09-01T01:00:00.123Z') then raise exception 'Timestamp changed';end if;
 checks:=array_append(checks,'Original timestamp retains milliseconds');
 if not exists(select 1 from public.shot_notes where owner_id=a and notes='Private original note') then raise exception 'Notes lost';end if;
 checks:=array_append(checks,'Private shot note survives');
 if not exists(select 1 from public.coffee_submissions where owner_id=a and proposed_data->>'name'='Sample Natural' and status='pending' and proposed_data->>'roastLevelSource'='estimated') then raise exception 'Provenance lost';end if;
 checks:=array_append(checks,'New cached coffee remains unverified and estimated');
 if (select current_library_entry_id from public.workspace_state where owner_id=a)<>private.import_id(a,'coffee','c1') then raise exception 'Wrong pin';end if;
 checks:=array_append(checks,'Adding unlogged coffee does not replace Current Coffee');
 select source_document into archived from private.import_batches where owner_id=a;
 if archived is distinct from doc then raise exception 'Source archive loss';end if;
 checks:=array_append(checks,'Complete source including legacy metadata archived unchanged');
 if (select count(*) from public.community_shots)>0 then raise exception 'Legacy aggregate published';end if;
 checks:=array_append(checks,'Legacy aggregate samples never become community shots');
 perform set_config('request.jwt.claim.sub',b::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);
 execute 'set local role authenticated';
 if (select count(*) from public.shots)<>0 then raise exception 'Other users see history';end if;
 checks:=array_append(checks,'Other member cannot see imported private history');
 bad:=jsonb_set(doc,'{data,shots,2,timeS}','999');
 rejected:=false;begin perform public.dic_preview_import(b,bad);exception when check_violation then rejected:=true;end;
 if not rejected then raise exception 'Invalid observation passed';end if;
 execute 'reset role';
 if exists(select 1 from public.setups where owner_id=b) then raise exception 'Partial import left over';end if;
 checks:=array_append(checks,'Late invalid record rolls back all earlier records');
 execute 'set local role authenticated';
 bad:=jsonb_set(doc,'{data,experiments}','[{"id":"e"}]');
 rejected:=false;begin perform public.dic_preview_import(b,bad);exception when invalid_parameter_value then rejected:=true;end;
 if not rejected then raise exception 'Unsupported experiment discarded';end if;
 checks:=array_append(checks,'Unsupported experiment is blocked rather than dropped');
 bad:=doc||'{"password":"do-not-upload-secrets"}'::jsonb;
 rejected:=false;begin perform public.dic_preview_import(b,bad);exception when invalid_parameter_value then rejected:=true;end;
 if not rejected then raise exception 'Secret accepted';end if;
 checks:=array_append(checks,'Credential-bearing backup rejected');
 -- Restore drill from stored source into a second isolated test identity.
 p:=public.dic_preview_import(b,archived);r:=public.dic_commit_import(b,archived,p->>'reviewHash',true);
 if (r->>'shots')::int<>3 then raise exception 'Source replay failed';end if;
 execute 'reset role';
 if (select sum(dose_g) from public.shots where owner_id=a)<>(select sum(dose_g) from public.shots where owner_id=b)
 or (select sum(time_s) from public.shots where owner_id=a)<>(select sum(time_s) from public.shots where owner_id=b) then raise exception 'Restored observations differ';end if;
 checks:=array_append(checks,'Archived source reconstructs observations in isolated restore drill');
 perform set_config('request.jwt.claim.sub',pending::text,true);perform set_config('request.jwt.claims',jsonb_build_object('sub',pending,'role','authenticated')::text,true);
 execute 'set local role authenticated';rejected:=false;
 begin perform public.dic_preview_import(pending,doc);exception when insufficient_privilege then rejected:=true;end;
 if not rejected then raise exception 'Pending member admitted';end if;
 checks:=array_append(checks,'Non-admitted account cannot preview');
 execute 'reset role';execute 'set local role anon';rejected:=false;
 begin perform public.dic_preview_import(a,doc);exception when insufficient_privilege then rejected:=true;end;
 if not rejected then raise exception 'Anonymous access';end if;
 execute 'reset role';checks:=array_append(checks,'Anonymous API access denied');
 insert into dic_import_test_results values(jsonb_build_object('passed',array_length(checks,1),'checks',checks,'fixtures','rolled back','scope','Database role tests; not browser login or disaster recovery'));
end $$;
select result from dic_import_test_results;
rollback;
